template:
% 参数由系统自动注入：\def\radius{3} \def\anglet{270} \def\arcspan{120} \def\angleoffset{120} \def\showtangent{1} \def\showchord{1} \def\showangle{1} \def\showinscribedangle{0} \def\showcentralangle{0} \def\showcenter{1} \def\labelt{T} \def\labela{A} \def\labelc{C} \def\showcoord{0} \def\cx{0} \def\cy{0}
% 视觉归一化：区分坐标模式与裸图模式
\ifnum\showcoord>0
  \pgfmathtruncatemacro{\xleft}{floor(\cx - \radius - 0.8)}
  \pgfmathtruncatemacro{\xright}{ceil(\cx + \radius + 0.8)}
  \pgfmathtruncatemacro{\ybottom}{floor(\cy - \radius - 0.8)}
  \pgfmathtruncatemacro{\ytop}{ceil(\cy + \radius + 0.8)}
  \pgfmathsetmacro{\xrange}{\xright - \xleft}
  \pgfmathsetmacro{\yrange}{\ytop - \ybottom}
  \pgfmathsetmacro{\figscale}{6.0 / max(\xrange, \yrange)}
\else
  \pgfmathsetmacro{\figscale}{3 / \radius}
\fi
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
% 角弧半径统一按「弧长约 0.30cm」反推：固定半径的角弧在小角度下弧长会退化到亚像素，
% 本模板的弦切角与圆周角都等于 arcspan/2，小 arcspan 时必须放大半径才看得见。
\pgfmathsetmacro{\arctarget}{0.30/\figscale*57.2958}
% 弦切角 = 同弧圆周角 = arcspan/2，两处角弧用同一个目标半径
\pgfmathsetmacro{\halfspan}{\arcspan/2}
\pgfmathsetmacro{\needhalf}{\arctarget/max(\halfspan,0.5)}
% 三个圆上点的位置角：T 为切点，A = T 沿逆时针转 arcspan，C 再沿逆时针转 angleoffset（落在另一段弧上）
\pgfmathsetmacro{\angA}{\anglet + \arcspan}
\pgfmathsetmacro{\angC}{\anglet + \arcspan + \angleoffset}
\pgfmathsetmacro{\Tx}{\radius*cos(\anglet)}
\pgfmathsetmacro{\Ty}{\radius*sin(\anglet)}
\pgfmathsetmacro{\Ax}{\radius*cos(\angA)}
\pgfmathsetmacro{\Ay}{\radius*sin(\angA)}
\pgfmathsetmacro{\Cx}{\radius*cos(\angC)}
\pgfmathsetmacro{\Cy}{\radius*sin(\angC)}
% 切线方向：垂直于半径 OT，取逆时针切向 anglet+90（该方向与弦 TA 夹出的角所夹弧正好是 T 逆时针到 A 的弧）
\pgfmathsetmacro{\tdx}{cos(\anglet+90)}
\pgfmathsetmacro{\tdy}{sin(\anglet+90)}
% 以下角弧参数只依赖入参，全部提到 tikzpicture 之前，图里只剩 \draw
% 弦切角：顶点 T，起边为切线的逆时针方向，终边为弦 TA
\pgfmathsetmacro{\lenchord}{sqrt((\Ax-\Tx)^2 + (\Ay-\Ty)^2)}
\pgfmathsetmacro{\sangct}{\anglet + 90}
\pgfmathsetmacro{\erawct}{atan2(\Ay-\Ty,\Ax-\Tx)}
\pgfmathsetmacro{\edifct}{\erawct - \sangct}
\pgfmathsetmacro{\eangct}{\sangct + \edifct - 360*round(\edifct/360)}
% 半径先按目标弧长反推，再被两边长度限住：切线边画到 1.15*radius，弦边长 lenchord，
% 取 0.55 倍是为了角弧不越过弦端点 A（那里有 A 的圆点和字母）
\pgfmathsetmacro{\arcrct}{min(max(0.42/\figscale, \needhalf), \radius*0.55, \lenchord*0.55)}
% 同弧圆周角 ∠TCA（与弦切角相等）
\pgfmathsetmacro{\lencit}{sqrt((\Tx-\Cx)^2 + (\Ty-\Cy)^2)}
\pgfmathsetmacro{\lencia}{sqrt((\Ax-\Cx)^2 + (\Ay-\Cy)^2)}
\pgfmathsetmacro{\sangci}{atan2(\Ty-\Cy,\Tx-\Cx)}
\pgfmathsetmacro{\erawci}{atan2(\Ay-\Cy,\Ax-\Cx)}
\pgfmathsetmacro{\edifci}{\erawci - \sangci}
\pgfmathsetmacro{\eangci}{\sangci + \edifci - 360*round(\edifci/360)}
\pgfmathsetmacro{\arcrci}{min(max(0.42/\figscale, \needhalf), \lencit*0.55, \lencia*0.55)}
% 圆心角 ∠TOA：逆时针从 anglet 扫到 angA，与弦切角所夹弧一致（arcspan 可超过 180 度）
\pgfmathsetmacro{\needspan}{\arctarget/max(\arcspan,0.5)}
\pgfmathsetmacro{\carcr}{min(max(0.5/\figscale, \needspan), \radius*0.42)}
% 圆心标注放在背离弧 TA 的一侧，避免压住圆心角的两条半径 OT、OA
\pgfmathsetmacro{\obis}{\anglet + \halfspan + 180}
% 弦切角的两条边是切线与弦 TA，两者都画出来才有角可标
\pgfmathsetmacro{\ctshow}{\showtangent*\showchord}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
    % ===== 坐标系（showcoord=1 时绘制）=====
  \ifnum\showcoord>0
    \draw[->, thick] (\xleft-0.5, 0) -- (\xright+0.5, 0) node[right] {$x$};
    \draw[->, thick] (0, \ybottom-0.5) -- (0, \ytop+0.5) node[above] {$y$};
  \fi
  \fill ({\cx+\Tx},{\cy+\Ty}) circle [radius=\dotr pt];
  \node at ({\cx+1.16*\Tx},{\cy+1.16*\Ty}) {$\labelt$};
  \fill ({\cx+\Ax},{\cy+\Ay}) circle [radius=\dotr pt];
  \node at ({\cx+1.16*\Ax},{\cy+1.16*\Ay}) {$\labela$};
\end{tikzpicture}
